// src/facets/controls.rs — the facet's own module; src/main.rs adds its two FACET WIRING lines.
// World (src/main.rs) holds pos: Vec2, jumps: u32 and paused: bool.
use super::World;
use genex::actions::{controls_panel, glyph_ui, ActionId, Anchor, ContextId, ControlId, ShowWhen, StickMode, UI};
use genex::prelude::*;
use genex::ui::Menu;

const PLAY: ContextId = ContextId::new("play");
const SYSTEM: ContextId = ContextId::new("system");
const MOVE: ActionId = ActionId::new("move");
const JUMP: ActionId = ActionId::new("jump");
const PAUSE: ActionId = ActionId::new("pause");
const STICK: ControlId = ControlId::new("stick");
const HOP: ControlId = ControlId::new("hop");
const MENU: ControlId = ControlId::new("menu");

pub fn wire(game: &mut Game<World>) {
    let play = Context::new(PLAY, 0)
        .axis2(MOVE, &[Binding::WASD, Binding::Stick(Stick::Left), Binding::Touch(STICK)])
        .button(JUMP, &[Key::Space.into(), Binding::Pad(PadButton::South), Binding::Touch(HOP)])
        .when(Condition::Press);
    // Escape and the pad's home button are the system's: pause on P, Start or the on-screen button.
    let system = Context::new(SYSTEM, 1)
        .button(PAUSE, &[Key::KeyP.into(), Binding::Pad(PadButton::Start), Binding::Touch(MENU)])
        .when(Condition::Press);
    game.input(ActionMap::new().context(play).context(system));
    // Drawn only on a touch screen; drawn or not, the controls read the same.
    game.touch_controls(
        TouchControls::new()
            .stick(STICK, Anchor::BottomLeft([160.0, 160.0]), 70.0, StickMode::Floating)
            .button(HOP, "Jump", Anchor::BottomRight([120.0, 120.0]), 48.0)
            .button(MENU, "Pause", Anchor::TopRight([50.0, 50.0]), 30.0)
            .show(ShowWhen::Touch),
    );
    game.on_update(|sim, ctx| {
        sim.world.pos += ctx.actions.axis2(MOVE) * 4.0;
        if ctx.actions.fired(JUMP) {
            sim.world.jumps += 1;
        }
        if ctx.actions.fired(PAUSE) {
            let paused = !sim.world.paused;
            set_paused(&mut sim.world, ctx, paused);
        }
    });
    game.on_ui(|sim, ui, ctx| {
        // A prompt is display text ("Space", "Cross"): draw it, never keep its label in the world.
        glyph_ui(ui, &ctx.actions.glyph(JUMP));
        if sim.world.paused {
            if Menu::new("pause").item("resume", "Resume").back("resume").show(ui) == Some("resume") {
                set_paused(&mut sim.world, ctx, false);
            }
            controls_panel(ui); // the player's rebinds, saved as genex-input.json
        }
    });
    game.probe("jumps", |sim| json!(sim.world.jumps));
    game.demo("touch-jump", |driver| {
        // The jump button's centre: 120 px in from the bottom-right corner of a 960 x 540 world.
        driver.inject(Input::touch_start(1, 840.0, 420.0));
        driver.advance_ms(50);
        driver.inject(Input::touch_end(1, 840.0, 420.0));
        driver.advance_ms(50);
        json!({ "jumps": driver.sim().world.jumps })
    });
}

/// The pause menu takes the `ui` context; play stops reading until it closes.
fn set_paused(world: &mut World, ctx: &Ctx, paused: bool) {
    world.paused = paused;
    if paused {
        ctx.actions.disable(PLAY);
        ctx.actions.enable(UI);
    } else {
        ctx.actions.enable(PLAY);
        ctx.actions.disable(UI);
    }
}
